-- Rollback for hoai-2021-md-verification-pack.sql (2026-09-05 md pass, written 2026-09-07).
-- Reverts ONLY rows this pack touched (identified by the verification_note tag) and ONLY for standard
-- HOAI-2021 (joined through worksheet_templates -> standards.code).
-- Prior state, taken from the prod export made for this pass:
--   * all 94 fields carried verification_status = imported_unverified (0 verified_against_standard,
--     0 corrected), verification_quote = null, verification_note = null, verified_at = null;
--   * all 6 equations already carried verification_status = verified_against_standard with
--     verification_quote = null and verification_note = null. The pack only BACKFILLS quote+note+verified_at,
--     so the rollback restores quote/note/verified_at to null and leaves verification_status alone.
-- No transaction control in this file: apply-pack.mjs supplies BEGIN/COMMIT and implements --dry-run by
-- rolling back; an inline commit would end that transaction early and turn a dry run into a real apply.

-- ---- fields (status + quote + note + verified_at) - prior status = imported_unverified (94 rows) ----
update public.fields f set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
 where wt.id = f.worksheet_template_id and s.code = 'HOAI-2021'
